// Act 4 underground (docs/design/04-the-list.md; index in docs/art-act4.md, "Underground").
// sisters (objects): the Three Sisters as beam pumps, 3 tiles tall (top row over the wall face; collision is the
//   bottom two rows): stout (3 wide), thin (1), middle (2).
//   Tiles <name>_<state>_x<c>y<r>[_<f>]: state sleep (still), cough (3 frames), run (4 frames);
//   middle_* has the copper throat fitted; middle_empty_x<c>y<r> is the empty socket.
//   wake_shut / wake_open / wake_turn_0..1 (wake-valves); over_shaft_<f> / over_shaft_still,
//   over_shaft_bearing_<f> / _still, over_shaft_end_w (the drive shaft, overhead).
// pumphall (ground): grate_<full|drain|dry|burst>_<l|r>[_<f>] (2 wide); flood_film_<f>, flood_<f>,
//   flood_edge_<n|s|e|w>_<f> (the dry side named); erung_top_shut/open/bang_<f>, erung_bot.
// tidewheel: wheel_x<c>y<r> (still) and wheel_turn_x<c>y<r>_<f> (4x6 tiles). tide_channel: chan_<slack|rush>[_<w|e>]_<f>, day_grate.
// eshaft: rungs[_wet|_dry|_light]_<l|r>, rungs_foot_<l|r>, side[_wet]_<l|r>, slab_<l|r>, slab_open_<l|r>.
// seacave: rock, rock_face_a/b, rock_edge_<e|w|n>, sand, sand_b, sand_shells, sand_wet, pool_<l|r>_<f>, mouth_<l|r>_<f>.
// seagrate: fgrate_<l|r> (still), fgrate_turn_<l|r>_<f>.
// mainpipe: the main along the west wall (x1): pipe_wall_top/bot (north wall face), pipe_run, pipe_run_b, pipe_flange,
//   pipe_end (objects); pipe_weep_<f> (intact, weeping); pipe_split_<f> (the burst) with overhead spray
//   over_spray_<n|m|s><a|b>_<f> in the two columns east of it and over_spray_pn/ps_<f> over the pipe above/below.

